using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new() { Name = "MyMcpServer", Version = "1.0.0" };
})
.WithHttpTransport()
.WithTools<MyTools>()
.WithResources<MyResources>();

var app = builder.Build();

app.MapMcp("/mcp");

app.Run();

// ── Tools ───────────────────────────────────────────────────────────────────

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo", Title = "Echo Tool", ReadOnly = true)]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add", Title = "Add Numbers", ReadOnly = true)]
    public static string Add(double a, double b) => $"Result: {a + b}";
}

// ── Resources ───────────────────────────────────────────────────────────────

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "app-config",
        Title = "Application Configuration",
        MimeType = "application/json")]
    public static string GetAppConfig() =>
        """
        {
          "appName": "MyMcpServer",
          "version": "1.0.0",
          "maxConnections": 100,
          "features": ["tools", "resources"]
        }
        """;

    [McpServerResource(
        UriTemplate = "config://app/status",
        Name = "app-status",
        Title = "Server Status",
        MimeType = "application/json")]
    public static string GetStatus() =>
        $$"""
        {
          "status": "healthy",
          "uptime": "{{Environment.TickCount64 / 1000}}s"
        }
        """;
}

